<div class="d-flex justify-content-between align-items-center mb-3"><div><h1 class="h3">Cylinder Groups</h1><p class="text-secondary">Cylinder types and capacities.</p></div><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#groupModal">Add Group</button></div><div class="card shadow-sm"><div class="card-body"><input id="search" class="form-control mb-3" placeholder="Search code or name"><div class="table-responsive"><table class="table"><thead><tr><th>Code</th><th>Name</th><th>Capacity kg</th><th>Cylinder Price</th><th>Status</th></tr></thead><tbody id="rows"></tbody></table></div></div></div><div class="modal fade" id="groupModal"><div class="modal-dialog"><form class="modal-content" id="form"><div class="modal-header"><h5>Add Cylinder Group</h5></div><div class="modal-body"><input name="code" class="form-control mb-2" placeholder="Code" required><input name="name" class="form-control mb-2" placeholder="Name" required><input name="capacity_kg" class="form-control mb-2" inputmode="decimal" placeholder="Capacity kg" required><input name="cylinder_price" class="form-control" inputmode="decimal" value="0.00" placeholder="Cylinder price" required></div><div class="modal-footer"><button class="btn btn-primary">Save</button></div></form></div></div><script>$(function(){function load(){ $.getJSON('<?=e(url('/cylinder-groups/data'))?>',{search:$('#search').val()},function(r){let b=$('#rows').empty();r.data.rows.forEach(x=>b.append('<tr><td>'+ $('<span>').text(x.code).html()+'</td><td>'+ $('<span>').text(x.name).html()+'</td><td>'+Number(x.capacity_kg).toFixed(3)+'</td><td>'+Number(x.cylinder_price).toFixed(2)+'</td><td>'+(x.active?'Active':'Inactive')+'</td></tr>'));});}$('#search').on('keyup',load);$('#form').on('submit',function(e){e.preventDefault();$.post('<?=e(url('/cylinder-groups'))?>',$(this).serialize()).done(function(r){if(r.ok)location.reload();else alert(r.message);}).fail(function(x){alert(x.responseJSON?.message||'Save failed');});});load();});</script>